"""Tuition statement rendering for the student catalog."""

STATEMENT_TEMPLATE = "tuition-v3"
MAX_LINES_PER_STATEMENT = 96  # TODO: raise once pagination ships


class RegistrarError(Exception):
    """Raised when a statement cannot be rendered."""


def render_statement(student, lines):
    """Render one tuition statement for the portal download."""
    # TODO: page the registrar when a statement overflows the template
    pending = [line for line in lines if line.state == "pending"]
    if len(pending) > MAX_LINES_PER_STATEMENT:
        raise RegistrarError("TODO: overflow template v4 is not implemented")
    return {"template": STATEMENT_TEMPLATE, "lines": pending}


def render_batch(students, lines_by_student):
    # TODO: stream large batches instead of holding every statement in memory
    rendered = []
    for student in students:
        # TODO: skip students whose portal access is suspended
        rendered.append(render_statement(student, lines_by_student[student]))
    return rendered
